 // e.g. external-dependency, stamped at draft time -- never reaches buildQuestion; see
 // classifyBlockedTask's own header).
 const CLASSIFIERS = [
+  {
+    // 2026-09-06: structured-flag precedence. A sibling gate (local-draft.js) stamps
+    // task.reviewInconclusive === true on review-gate inconclusive tasks. Recognizing
+    // that STRUCTURED field first makes it take precedence over the fragile free-text
+    // 'inconclusive' keyword match below (REASON_CATEGORIES) -- the flag is a precise,
+    // mechanical signal, exactly the preference this registry's header argues for. The
+    // keyword path stays untouched as a pure fallback for legacy tasks that predate the
+    // flag. faultSide/retryable mirror the keyword entry's values so classification of a
+    // flagged task is identical to a keyword-matched one -- only the recognition source
+    // is more reliable.
+    name: 'inconclusive-review-flag',
+    classify(task) {
+      if (task && task.reviewInconclusive === true) {
+        return { category: 'inconclusive-review', faultSide: 'model', retryable: true };
+      }
+      return null;
+    },
+  },
   {
     name: 'external-dependency',
     // Stamped at DRAFT time by local-agentic-write-draft.js's detectExternalDependency
