+// keyword path intact as a legacy fallback.
+
+test('flag-wins: reviewInconclusive===true classifies inconclusive-review even when the reason would NOT keyword-match', () => {
+  const result = classifyBlockedTask({ reviewInconclusive: true, blockedReason: 'some unrelated text with no keyword' });
+  assert.equal(result.category, 'inconclusive-review');
+  assert.equal(result.faultSide, 'model');
+  assert.equal(result.retryable, true);
+});
+
+test('flag-overrides-other-structural: reviewInconclusive===true wins even over a structural classifier that would otherwise match first', () => {
+  // blockedReason mentions an external dependency AND unreliable grounding is present --
+  // both are structural classifiers ordered BEFORE the keyword spread, yet the flag must
+  // take precedence over all of them.
