+    reviewInconclusive: true,
+    blockedReason: 'external dependency timeout',
+    needsClarification: { reason: 'external-dependency' },
+  };
+  assert.equal(classifyBlockedTask(task).category, 'inconclusive-review');
+});
+
+test('keyword-fallback-still-works: no reviewInconclusive field still resolves inconclusive-review via the keyword path (legacy)', () => {
+  const result = classifyBlockedTask({ blockedReason: 'review was inconclusive' });
+  assert.equal(result.category, 'inconclusive-review');
+  assert.equal(result.faultSide, 'model');
+  assert.equal(result.retryable, true);
+});
+
+test('explicit-false-falls-through: reviewInconclusive===false does NOT short-circuit; keyword path still applies', () => {
+  const result = classifyBlockedTask({ reviewInconclusive: false, blockedReason: 'review was inconclusive' });
+  assert.equal(result.category, 'inconclusive-review');
+  // ...and with NO keyword match and flag false, it falls through to uncategorized.
+  const negative = classifyBlockedTask({ reviewInconclusive: false, blockedReason: 'a genuinely novel failure nobody has a keyword for' });
+  assert.equal(negative.category, 'uncategorized');
+});
+
+test('flag-without-reason: reviewInconclusive===true alone (no blockedReason) is sufficient', () => {
